def classify(ip):
    first, second = (int(x) for x in ip.split(".")[:2])
    if first == 10:
        return "private"
    if first == 172 and 16 <= second <= 31:
        return "private"
    if first == 192 and second == 168:
        return "private"
    if first == 127:
        return "loopback"
    return "public"

