def usable_hosts(prefix):
    if prefix >= 32:
        return 1
    if prefix == 31:
        return 2
    return 2 ** (32 - prefix) - 2

def find(items, target):
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
